INSERT INTO `f_corps` (`idmessage`, `contenu`) VALUES
(1, '  :mrgreen: Voil&agrave; le premier message du forum.\r\n\r\nSelon vos d&eacute;sirs voici un forum pour vous.\r\n\r\nChaque &eacute;quipe dispose &eacute;galement de son forum priv&eacute;  :!: \r\n\r\nBon blabla  :wink: '),
(2, 'Test du forum n&deg;1'),
(3, 'test n&deg;2\r\n\r\n\r\n[quote]Test du forum n&deg;1[/quote]'),
(4, 'test n&deg;3\r\n\r\n\r\n[quote]test n&deg;2\r\n\r\n\r\n[quote]Test du forum n&deg;1[/quote][/quote]'),
(5, '\r\nmoi aussi je peux faire un test?:lol: \r\n\r\n[quote]Test du forum n&deg;1[/quote] '),
(6, '\r\n\r\n[quote]\r\nmoi aussi je peux faire un test?:lol: \r\n\r\n[quote]Test du forum n&deg;1[/quote] [/quote]\r\n\r\n&lt;Flood pour test&gt;\r\n\r\nNon tu es en plus value n&eacute;gative !!!!\r\n'),
(7, 'Tu triche pour &ecirc;tre positif :evil: '),
(8, '\r\n\r\n\r\n[quote]Tu triche pour &ecirc;tre positif :evil: [/quote]\r\n\r\nJaloux suis en positif Moi !'),
(9, 'Moi jaloux:?: , sa me g&egrave;ne beaucoup ce que tu dis:cry: ,\r\nde toute fasson gagner en trichant n\'a jamais rien raporter &agrave; personne:wink: \r\n\r\n[quote]\r\n\r\n\r\n[quote]Tu triche pour &ecirc;tre positif :evil: [/quote]\r\n\r\nJaloux suis en positif Moi ![/quote]   '),
(10, 'Alors que pensez-vous de ce forum ?\r\n\r\nQu\'aimerai vous voir modifi&eacute; ou ajout&eacute; dans ce forum ?'),
(11, 'bon je suis nouveau sur le site et je sais pa kelle action acheter...\r\ny\'en a tellemen, que choisir?'),
(12, 'Bonjour, que pensez vous de l\'idee d\'un calculateur de taxe? \r\nMerci bon trade \r\neD '),
(13, 'bonne id&eacute;e\r\n\r\n\r\n[quote]Bonjour, que pensez vous de l\'idee d\'un calculateur de taxe? \r\nMerci bon trade \r\neD [/quote]'),
(14, 'Je trouve &ccedil;a plutot interessant surtout quand  on est nouveau sur le jeux. Sa permetrai de calculer a quelle moment nous somme rentable.\r\n\r\n\r\n[quote]Bonjour, que pensez vous de l\'idee d\'un calculateur de taxe? \r\nMerci bon trade \r\neD [/quote]'),
(15, 'Excellente id&eacute;e, dans le m&ecirc;me esprit un choix de broker pourrait &ecirc;tre impl&eacute;ment&eacute;  en se basant sur les diff&eacute;rents brooker existant (internet ou banques) :D \r\n\r\n\r\n[quote]bonne id&eacute;e\r\n\r\n\r\n[quote]Bonjour, que pensez vous de l\'idee d\'un calculateur de taxe? \r\nMerci bon trade \r\neD [/quote][/quote]'),
(16, 'c koi un brooker?\r\n\r\n'),
(17, '[quote]c koi un brooker?\r\n\r\n[/quote]\r\n\r\nbroker = courtier: exemple ta banque ou boursorama\r\n\r\nhttp://www.i-services.net/membres/annuaire/voir_sites.php?user=109201&amp;idcat=125072&amp;show=cat'),
(18, 'juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) '),
(19, 'c\'est justement l&agrave; qu\'est tout le travail lorsqu\'on arrive ! de trouver des actions sympa !\r\n\r\nca prend un peu de temps mais ce travail est necessaire et doit restez personnel!\r\ncourage!  8) '),
(20, 'Et surtout acheter au bon moment ^^ \r\n\r\n\r\n'),
(21, 'Vous voulez que le calcul de plus value tiennent compte des frais de courtage ?\r\n\r\n\r\n[quote]juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) [/quote]'),
(22, 'Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l’action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ?\r\n\r\n\r\n[quote]juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) [/quote][/quote]'),
(23, 'Donc dans le formulaire d\'achat/vente ?\r\n\r\nCe serait un calcul en direct ? Avec un champ d\'info taxe\r\n\r\n\r\n[quote]Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l&amp;#8217;action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n[/quote]'),
(24, 'En retour du temps et des d&eacute;penses que j\'ai effectu&eacute; pour votre amusement vous pouvez supporter le site en vous inscrivant gratuitement sur le site de [url=&quot;http://fun-trades.com/index.php?ref=5737&quot;]fun-trades[/url] et en remplissant votre portefeuille virtuelle d\'action NetTrader.\r\n\r\nQue pensez-vous du jeu Fun-Trades ?'),
(25, 'oui Si non une colone de plus sur le tableau (apr&eacute;s plus value) avec comme intituler taxe et en dessous le montant pour chaque action\r\n\r\n\r\n[quote]Donc dans le formulaire d\'achat/vente ?\r\n\r\nCe serait un calcul en direct ? Avec un champ d\'info taxe\r\n\r\n\r\n[quote]Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l&amp;#8217;action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n[/quote][/quote]'),
(26, '\r\nsi la plue value tennait compte des frais de courtage directement cela serait plus facile, non ?\r\n\r\n[quote]Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l’action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ?\r\n\r\n\r\n[quote]juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) [/quote][/quote][/quote]'),
(27, 'J\'aimerai savoir s\'il serait possible de cr&eacute;er un algorithme qui permettrait de voir les portefeuilles de nos &eacute;quipiers? Merci'),
(28, 'au lieu de nou dire % des liquidit&eacute;s, pourkoi ne pa simplement l\'ecrire en euro, on s\'y pert parfois!\r\nou bien en choisissant un nombre d\'action, pk ne pa nou calcul&eacute; leur valeur totale avan d\'effectu&eacute; l\'achat\r\n&ccedil;a nous faciliterait les calcul !'),
(29, 'Je ne trouve pas car du coup tu ne vois pas l\'&eacute;volution r&eacute;el de l\'action. mais bon c\'est une solution comme une autre. Je suis ouvert au deux\r\n\r\n\r\n[quote]\r\nsi la plue value tennait compte des frais de courtage directement cela serait plus facile, non ?\r\n\r\n[quote]Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l’action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ?\r\n\r\n\r\n[quote]juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) [/quote][/quote][/quote][/quote]'),
(30, 'oui c\' est exacte ou alors faire une colonne en plus qui indiquerait la plus value incluant les frais de courtage comme cela on aurait les deux information\r\n\r\n\r\n[quote]Je ne trouve pas car du coup tu ne vois pas l\'&eacute;volution r&eacute;el de l\'action. mais bon c\'est une solution comme une autre. Je suis ouvert au deux\r\n\r\n\r\n[quote]\r\nsi la plue value tennait compte des frais de courtage directement cela serait plus facile, non ?\r\n\r\n[quote]Je trouverai pr&eacute;f&eacute;rable que &ccedil;a le calcul a cot&eacute;, car comme sa on voit rapidement si l’action est mont&eacute; ou non. Mais si  ce n\'est pas possible alors que cela l\'inclus dans la plus value.\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ?\r\n\r\n\r\n[quote]juste le calculateur de taxe en evidence ca serait deja un plus c sur!  :) [/quote][/quote][/quote][/quote][/quote]'),
(31, 'Pour les autres joueurs , ca ne vous derangerai pas que les membres de votre groupe puissent voir votre portefeuille ?\r\n\r\n\r\n[quote]J\'aimerai savoir s\'il serait possible de cr&eacute;er un algorithme qui permettrait de voir les portefeuilles de nos &eacute;quipiers? Merci[/quote]'),
(32, ':( sa ne m\'aide pa bocoup &ccedil;a \r\nvous pouv&eacute; me donn&eacute; kelke conseil o moin, autr ke acheter au bon moment?\r\n\r\n'),
(33, 'Oui en effet il faudrait que ce soit plus clair.\r\n\r\nIl faudrait proposer un exemple de contenu de liste d&eacute;roulante \r\n\r\n\r\n[quote]au lieu de nou dire % des liquidit&eacute;s, pourkoi ne pa simplement l\'ecrire en euro, on s\'y pert parfois!\r\nou bien en choisissant un nombre d\'action, pk ne pa nou calcul&eacute; leur valeur totale avan d\'effectu&eacute; l\'achat\r\n&ccedil;a nous faciliterait les calcul ![/quote]'),
(34, 'Tu trouveras des informations utiles sur le site :\r\n\r\n[url]http://blog.nettrader.fr[/url]\r\n\r\nIl y a diff&eacute;rends courants au niveau d&eacute;cisionnel. Tu peut te documenter sur l\'analyse technique ( se focalisant sur les graphiques ) ou sur l\'analyse fondamentale ( sur l\'entreprise elle-m&ecirc;me ) .\r\n\r\nPour un d&eacute;but, et de fa&ccedil;on virtuelle tu peut te borner &agrave; &eacute;couter les nouvelles &agrave; la t&eacute;l&eacute; et acheter l\'entreprise correspondante  en fonction de la logique. Tu peut juste regarder sur les site finances genre finance.yahoo.fr et acheter les actions &agrave; la hausse ..\r\n\r\nEnfin bref, au fur et &agrave; mesure du temps tu va apprendre un peu plus sur le fonctionnement de la bourse.\r\n\r\n\r\n[quote]:( sa ne m\'aide pa bocoup &ccedil;a \r\nvous pouv&eacute; me donn&eacute; kelke conseil o moin, autr ke acheter au bon moment?\r\n\r\n[/quote]'),
(35, 'merci\r\n\r\n'),
(36, '\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ? [/quote]\r\n\r\noui  :D '),
(37, 'non\r\n\r\n\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ? [/quote]\r\n'),
(38, 'Ce serait bien qu\'on puisse acheter des actions du Swiss market index (smi) ou du Nasdaq  de New York.'),
(39, 'pas n&eacute;cessairement il pourrait y avoir une colonne supl&eacute;mentaire avec la plue value incluant les frais de courtage comme &ccedil;a on aurrait un suivit des action plus les plus value exacte\r\n\r\n\r\nnon\r\n\r\n[quote]\r\n\r\n\r\n[quote]Vous voulez que le calcul de plus value tiennent compte des frais de courtage ? [/quote]\r\n[/quote]'),
(40, 'oui je suis d\'accord mais &agrave; ce moment la les entreprises du dow jones seraient plus appropri&eacute;es mais apr&egrave;s &ccedil;a peut faire beucou. C\'est un sujet &agrave; d&eacute;battre\r\n[quote]Ce serait bien qu\'on puisse acheter des actions du Swiss market index (smi) ou du Nasdaq  de New York.[/quote]'),
(41, 'oui mais alors il faudrait mettre en plus une somme en euros mais garder celle en pourcentage, car c\'est interessant. Et puis on a le nombre d\'actions qui compl&egrave;te \r\n\r\n\r\n[quote]Oui en effet il faudrait que ce soit plus clair.\r\n\r\nIl faudrait proposer un exemple de contenu de liste d&eacute;roulante \r\n\r\n\r\n[quote]au lieu de nou dire % des liquidit&eacute;s, pourkoi ne pa simplement l\'ecrire en euro, on s\'y pert parfois!\r\nou bien en choisissant un nombre d\'action, pk ne pa nou calcul&eacute; leur valeur totale avan d\'effectu&eacute; l\'achat\r\n&ccedil;a nous faciliterait les calcul ![/quote][/quote]'),
(42, 'Je volais savoir pr&eacute;cisemment quelles etaient les r&egrave;gles pour jouer en groupe?'),
(43, 'Juste pour voir ce que &ccedil;a donne le forum d\'&eacute;quipe... mieux que les messages en perso?\r\n\r\nPerso je trouve que la progression en trois jours de \r\n19 --&gt; 15 --&gt; 10 laisse pr&eacute;sager que la reprise est l&agrave;...\r\n\r\nMais pas trop les bons plans au niveau actions ...  A moins que je sois pass&eacute; &agrave; c&ocirc;t&eacute; de qqch ou que je doive changer mon spectre de dur&eacute;e...\r\n\r\nA voir \r\n\r\nSeeU All\r\n\r\nZOu\r\n\r\n'),
(44, 'Tout est dans le titre... Les dividendes font partie int&eacute;grante de l\'&eacute;valuation de certains titres (FT, air liquide,...), c\'est peut-&ecirc;tre possible de les int&eacute;grer. 3% de dividende c\'est une bonne dose de beurre dans les &eacute;pinards...\r\n\r\nSinon, pour les sp&eacute;culateurs forcenn&eacute;s, l\'achat &agrave; d&eacute;couvert est aussi une bonne strat&eacute;gie, compl&eacute;mentaire de la VAD. La &ccedil;&agrave; doit &ecirc;tre plus facile &agrave; int&eacute;grer.\r\n\r\nPour finir super boulot, le site est sensas....\r\n\r\n\r\nAknoth'),
(45, 'Salut &agrave; tous,\r\n\r\n\r\nJe sugg&egrave;re au developpeur du site de cr&eacute;er un tchat &eacute;gornomique pour  am&eacute;liorer la convivialit&eacute;.\r\nA chaque connexion sur le site, on entre dans le tchat.\r\n\r\nBien cordialement et au plaisir de tchater.\r\n\r\nUn trader.'),
(46, 'Bien il serait aussi sympa de g&eacute;n&eacute;raliser la visibilit&eacute; des portefeuille non pas au sein d\'un &eacute;quipe mais &agrave; la totalit&eacute; des joeurs.\r\n\r\nNous sommes tous l&agrave; pour &ecirc;tre encore meilleurs que demain.\r\nDe mon c&ocirc;t&eacute;, je suis class&eacute; actuellement 5ieme en 2 jours de trading et ca ne me derrange pas que kkun visualise mon portefeuille.\r\n\r\nMais le + grand plaisir serait d\'avoir un tchat o&ugrave; l\'on pourait tous tchatter.\r\nSeuls les plus assidus au tchat tisseront des liens amicaux et qui seront, peut &ecirc;tre les futures golen boys.\r\n\r\nCordialement.\r\nA+\r\n \r\n\r\n[quote]Pour les autres joueurs , ca ne vous derangerai pas que les membres de votre groupe puissent voir votre portefeuille ?\r\n\r\n\r\n[quote]J\'aimerai savoir s\'il serait possible de cr&eacute;er un algorithme qui permettrait de voir les portefeuilles de nos &eacute;quipiers? Merci[/quote][/quote]'),
(47, 'salut  a tous ,\r\noui ses vrai un petit parquet serai biens,pour echanger des idee,et aidee les nouveau.\r\n\r\n'),
(48, 'Les performances des joueurs sont cumul&eacute;es.\r\n\r\nLe jeu se d&eacute;roule en p&eacute;riode d\'un mois.\r\n\r\nLa progression calcul&eacute; est &eacute;gale &agrave; :\r\n\r\n(somme du capital en fin de mois - somme du capital en debut de mois ) / somme du capital en debut de mois\r\n\r\nAinsi un joueur qui a un capital plus &eacute;lev&eacute; que les autres aura plus d\'influance sur le groupe que les autres joueurs.\r\n\r\nA la fin du mois un indice or,argent et bronze permet de differencier les meilleurs groupes.\r\n\r\n\r\n[quote]Je volais savoir pr&eacute;cisemment quelles etaient les r&egrave;gles pour jouer en groupe?[/quote]'),
(49, '\r\nUn tchat pour discuter des actions ect ... oui! Pouvoir voir en permanence les portefeuilles des autres membres du groupe oui &eacute;galement ! ceux des autres joueurs non ca perds un peu l\'interet du jeu &agrave; savoir se retrouver en t&ecirc;te du classement de plus value  :wink: \r\n\r\n[quote]Pour les autres joueurs , ca ne vous derangerai pas que les membres de votre groupe puissent voir votre portefeuille ?\r\n\r\n\r\n[quote]J\'aimerai savoir s\'il serait possible de cr&eacute;er un algorithme qui permettrait de voir les portefeuilles de nos &eacute;quipiers? Merci[/quote][/quote]'),
(50, 'Je ne suis pas d\'accord pour que les gens ext&eacute;rieurs au groupe.\r\n'),
(51, 'Si vous avez des actions EADS vendez les juste avant la fin de la s&eacute;ance du 8 mars. Demain, ils vont annoncer les r&eacute;sultats, et je suis pr&ecirc;t &agrave; parier, que le cours va chuter. Ils ont pris du retard et les salari&eacute;s sont pr&ecirc;ts &agrave; faire gr&egrave;ve.'),
(52, 'C\'est vrai qu\'il serait bien de pouvoir int&eacute;grer les dividendes.'),
(53, 'Et le versement des dividendes se ferait quand ?'),
(54, 'Bonjour,\r\nje viens de commencer sur nettrader et &ccedil;a a l\'air tr&egrave;s bien, c\'est simple et efficace.\r\nAvoir la possibilit&eacute; de voir [b]l\'historique [/b]de nos valeurs d\'action et aussi du portefeuille global serait encore mieux.\r\nOn peut imaginer plein d\'autre visions graphiques... (camembert de r&eacute;partition des actions dans le portefeuille...)\r\n\r\nqu\'en pensez vous?'),
(55, 'Je pense que ce serait une excelente id&eacute;e de mettre un graphique affichant l\'historique de notre plus value, ou de la valeur de notre portefeuille.\r\n\r\n\r\n[quote]Bonjour,\r\nje viens de commencer sur nettrader et &ccedil;a a l\'air tr&egrave;s bien, c\'est simple et efficace.\r\nAvoir la possibilit&eacute; de voir [b]l\'historique [/b]de nos valeurs d\'action et aussi du portefeuille global serait encore mieux.\r\nOn peut imaginer plein d\'autre visions graphiques... (camembert de r&eacute;partition des actions dans le portefeuille...)\r\n\r\nqu\'en pensez vous?[/quote]'),
(56, '\r\n\r\n\r\n[quote]Et le versement des dividendes se ferait quand ?[/quote]\r\n\r\nen meme temp ke les entreprise les verse en realit&eacute; '),
(57, 'Nous sommes tous la pour s\'am&eacute;liorer et &eacute;changer nos comp&eacute;tences.\r\n\r\nJe suis persuad&eacute; que l\'union fait la force et que rester dans son coin et s\'autoanlyser ne suffit pas &agrave; &ecirc;tre encore + performant.\r\n\r\nC bien dommage de jouer en solo.\r\n'),
(58, '\r\nOui est ce comparer &agrave; l\'indice du CAC40.\r\n\r\nAinsi il sera facile de voir si l\'on superforme la CAC40\r\n\r\n\r\n[quote]Bonjour,\r\nje viens de commencer sur nettrader et &ccedil;a a l\'air tr&egrave;s bien, c\'est simple et efficace.\r\nAvoir la possibilit&eacute; de voir [b]l\'historique [/b]de nos valeurs d\'action et aussi du portefeuille global serait encore mieux.\r\nOn peut imaginer plein d\'autre visions graphiques... (camembert de r&eacute;partition des actions dans le portefeuille...)\r\n\r\nqu\'en pensez vous?[/quote]'),
(59, 'Sinc&eacute;rement, je trouve que le forum manquait vraiment.\r\nMaintenant, c\'est g&eacute;nial! :D '),
(60, 'je l\'avais demand&eacute; &agrave; l\'administrateur... l\'id&eacute;e lui paraissait int&eacute;ressnate (normal, &ccedil;a venait de moi).javascript:emoticon(\'8)\')\r\nMerci &agrave; lui... il a entendu ma voix !!!\r\n\r\n\r\n[quote]Juste pour voir ce que &ccedil;a donne le forum d\'&eacute;quipe... mieux que les messages en perso?\r\n\r\nPerso je trouve que la progression en trois jours de \r\n19 --&gt; 15 --&gt; 10 laisse pr&eacute;sager que la reprise est l&agrave;...\r\n\r\nMais pas trop les bons plans au niveau actions ...  A moins que je sois pass&eacute; &agrave; c&ocirc;t&eacute; de qqch ou que je doive changer mon spectre de dur&eacute;e...\r\n\r\nA voir \r\n\r\nSeeU All\r\n\r\nZOu\r\n\r\n[/quote] 8)  8) '),
(61, 'merci bien\r\n\r\n\r\n[quote]Les performances des joueurs sont cumul&eacute;es.\r\n\r\nLe jeu se d&eacute;roule en p&eacute;riode d\'un mois.\r\n\r\nLa progression calcul&eacute; est &eacute;gale &agrave; :\r\n\r\n(somme du capital en fin de mois - somme du capital en debut de mois ) / somme du capital en debut de mois\r\n\r\nAinsi un joueur qui a un capital plus &eacute;lev&eacute; que les autres aura plus d\'influance sur le groupe que les autres joueurs.\r\n\r\nA la fin du mois un indice or,argent et bronze permet de differencier les meilleurs groupes.\r\n\r\n\r\n[quote]Je volais savoir pr&eacute;cisemment quelles etaient les r&egrave;gles pour jouer en groupe?[/quote][/quote]'),
(62, '\r\n\r\n\r\n[quote]Nous sommes tous la pour s\'am&eacute;liorer et &eacute;changer nos comp&eacute;tences.\r\n\r\nJe suis persuad&eacute; que l\'union fait la force et que rester dans son coin et s\'autoanlyser ne suffit pas &agrave; &ecirc;tre encore + performant.\r\n\r\nC bien dommage de jouer en solo.\r\n[/quote]\r\n\r\nje suis d\'accord avec stro, on apprend plus vite des autre ke en apprenan tous seul.\r\n'),
(63, '\r\n\r\nPas mal comme id&eacute;e la conparaison de l\'evolution du portefeuille et du cac40'),
(64, 'Bonjour,\r\n\r\nEtant nouveau dans le jeu mais passionn&eacute; de trading, je viens de m\'apercevoir certaines surpercheries de certains utilisateurs qui sont devant moi.\r\n\r\nEn effet, je fais de l\'intradays en ayant de bonne performance et je viens d\'analyser le comportement certains joueurs qui sont devant moi.\r\n\r\nJe viens a l\'instant de trouver la cause de si belle performance que je trouve digne des meilleurs trader au monde.\r\nJe viens aussi de tester le bug du site et ca marche a merveille.\r\nProbablement que les gens qui sont devant moi utiliser ce bug.\r\n\r\nAmis  Administrateur &amp; concepteur du site, merci d\'entrer en contact avec moi pour connaitre ce bug afin que r&eacute;ellement soit dans les meilleurs de la listes les + comp&eacute;tents.\r\n\r\nLes &eacute;quipes dont je me tairai utilise le bug ?\r\n\r\nJe propose la correction du bug et le reset TOTAL des comptes utilisateurs.\r\n\r\n\r\nUn nouveau tr&egrave;s surpris du bug du jeu mais un passion&eacute; de bourse.\r\n\r\n\r\n'),
(65, 'On fait moins les malins aujourd\'hui!!!'),
(66, 'Tout d\'abord je tient a rassurer les joueurs je ne vais pas faire de reset du jeu.\r\n\r\nEnvoie moi un msg par ce formulaire  stp\r\n\r\nhttp://www.nettrader.fr/index.php?do=contactauteur\r\n\r\n\r\n[quote]Bonjour,\r\n\r\nEtant nouveau dans le jeu mais passionn&eacute; de trading, je viens de m\'apercevoir certaines surpercheries de certains utilisateurs qui sont devant moi.\r\n\r\nEn effet, je fais de l\'intradays en ayant de bonne performance et je viens d\'analyser le comportement certains joueurs qui sont devant moi.\r\n\r\nJe viens a l\'instant de trouver la cause de si belle performance que je trouve digne des meilleurs trader au monde.\r\nJe viens aussi de tester le bug du site et ca marche a merveille.\r\nProbablement que les gens qui sont devant moi utiliser ce bug.\r\n\r\nAmis  Administrateur &amp; concepteur du site, merci d\'entrer en contact avec moi pour connaitre ce bug afin que r&eacute;ellement soit dans les meilleurs de la listes les + comp&eacute;tents.\r\n\r\nLes &eacute;quipes dont je me tairai utilise le bug ?\r\n\r\nJe propose la correction du bug et le reset TOTAL des comptes utilisateurs.\r\n\r\n\r\nUn nouveau tr&egrave;s surpris du bug du jeu mais un passion&eacute; de bourse.\r\n\r\n\r\n[/quote]'),
(67, 'Bonjour a tous, tradeurs et tradeuses  :!: \r\n\r\nLe but de ce groupe est d\'augmenter dans l\'entraide; pour postuler, il faut connaitre les bases, ne pas &ecirc;tre trop en perte ( nous avons un but de victoire, car il ne faut pas oublier que la bourse reste un jeu.. dangereux, certes, mais un jeu malgr&eacute; tout, et NetTrader le rappel admirablement )\r\n\r\nUn forum personnel sera cr&eacute;er sous peu, a moins qu\'une partie de Nettrader ne soit allou&eacute; aux forums de groupe, d\'ici quelques temps.\r\n\r\nEn esperant avoir beaucoup de r&eacute;ponses.\r\n\r\n\r\nLeoden, allias Florent, Tradeur fictif depuis 3 mois, interress&eacute; a la bourse depuis 2 ans.'),
(68, 'Je me pr&eacute;sente, florent, 17 ans, en terminale scientifique, j\'suis surement jeune par rapport a certains, mais je suis sur que y\'a plus jeunes encore ( d&eacute;ja ) dans le &quot;monde&quot; de la bourse. \r\n\r\nA votre tour, succinte ou approfondie, faites nous part de votre identit&eacute;  :D '),
(69, 'je rajoute mon avis; cela permettrais en plus de d&eacute;couvrir les bugs utilis&eacute;s ( certaines progressions me sembles louche ! m&ecirc;me si a la bourse tout est possible ) mais surtout de - beaucoup - progresser en apprenant comment font les meilleurs !!!\r\n\r\n\r\n[quote]\r\n\r\n\r\n[quote]Nous sommes tous la pour s\'am&eacute;liorer et &eacute;changer nos comp&eacute;tences.\r\n\r\nJe suis persuad&eacute; que l\'union fait la force et que rester dans son coin et s\'autoanlyser ne suffit pas &agrave; &ecirc;tre encore + performant.\r\n\r\nC bien dommage de jouer en solo.\r\n[/quote]\r\n\r\nje suis d\'accord avec stro, on apprend plus vite des autre ke en apprenan tous seul.\r\n[/quote]'),
(70, 'g&eacute;nial, ce qu\'il manquait a la communaut&eacute; !!!\r\n\r\n\r\n[quote]Sinc&eacute;rement, je trouve que le forum manquait vraiment.\r\nMaintenant, c\'est g&eacute;nial! :D [/quote]'),
(71, 'Perso je trouve que c\'est une super id&eacute;e... Surtout que Man96 et moi sommes suisse donc toutes les entreprises que nous connaissons en suisse...ne sont pas sur nettrader!'),
(72, 'Eh&eacute; je vais pas te dire que tu as fait une bonne action je te connais tu le prendrais mal ;)\r\n\r\nMais effectivmeent c t une tr&egrave;s bonne id&eacute;e plut&ocirc;t que les messages unitaires ;)\r\n\r\n\r\n'),
(73, 'Alors si j\'ai bien compris les remarques malgr&eacute; le whisky dans le sang tout est bon &agrave; prendre (dans la limite du raisonnable).\r\n\r\nBon me rappelles plus vos achats mais enfin bon peu importe \r\n\r\nSInon mon petit didier tu triches tu &eacute;tais tellement bas au d&eacute;but du mois que maintenant tu as des taux de progression de ouf... c honteux comme proc&eacute;d&eacute;&eacute; ;)\r\n\r\n++\r\n\r\nZOu'),
(74, '\r\nTain j\'ai vendu &agrave; d&eacute;couvert sans m\'en rendre compte du LVMH et dans l\'affaire j\'ai fait des plus values avec la baisse  ...  et en plus j\'ai gav&eacute; de liquidit&eacute; dans l\'affaire! Enfin bon j\'ach&egrave;tre &agrave; tour de bras attention &ccedil;a va monter!!\r\n\r\nJsuis un ouf , faut pas que je pense et que je clique au pif \r\n\r\n'),
(75, 'kevin 16 ans je suis en 2nd et je decouvre la bourse, j\'aimerais plus tard acheter des actions. \r\n\r\n'),
(76, 'Bonjour,\r\n\r\nL\'administrateur ne voulant pas reseter le jeu, et les tricheurs ayant b&eacute;n&eacute;ficier depuis longue date du bug  o&ugrave; est l\'interet de son jeu ?\r\n\r\nC du n\'importe quoi :\r\nComment voulez vous faire de 80% voire du 200% en 1 ou 2 semaine.\r\nIl faut arretez les conneries meme avec un effet de levier 3.\r\n\r\n\r\nDe +, je ne vois pas en quoi le reset gene l\'administrateur pour les raisons suivantes :\r\n - les meilleurs resteront les meilleurs\r\n - les comptes des mauvais seront augment&eacute;s\r\n - et le nouveau trader comme moi (les v&eacute;ritable et non des escrot) seront interess&eacute; par son jeu.\r\n\r\nMerci de bien vouloir exprimer vos opinions.\r\n\r\nSi personne n\'est favorable, je  serais dans l\'obligation de quitter son jeu inutile a mon sens et promouvoir d\'autres similaires.\r\n\r\n\r\nAussi, si vous etes de veritables trader comme je le suis, echangeons nos experiences vous pouvez me contactez pas messagerie dans le site'),
(77, 'et ceux ki n\'on pa trich&eacute; et ki on un bon portefeuil? ki te dit k\'il sont pour un reset?\r\n\r\n\r\n[quote]Bonjour,\r\n\r\nL\'administrateur ne voulant pas reseter le jeu, et les tricheurs ayant b&eacute;n&eacute;ficier depuis longue date du bug  o&ugrave; est l\'interet de son jeu ?\r\n\r\nC du n\'importe quoi :\r\nComment voulez vous faire de 80% voire du 200% en 1 ou 2 semaine.\r\nIl faut arretez les conneries meme avec un effet de levier 3.\r\n\r\n\r\nDe +, je ne vois pas en quoi le reset gene l\'administrateur pour les raisons suivantes :\r\n - les meilleurs resteront les meilleurs\r\n - les comptes des mauvais seront augment&eacute;s\r\n - et le nouveau trader comme moi (les v&eacute;ritable et non des escrot) seront interess&eacute; par son jeu.\r\n\r\nMerci de bien vouloir exprimer vos opinions.\r\n\r\nSi personne n\'est favorable, je  serais dans l\'obligation de quitter son jeu inutile a mon sens et promouvoir d\'autres similaires.\r\n\r\n\r\nAussi, si vous etes de veritables trader comme je le suis, echangeons nos experiences vous pouvez me contactez pas messagerie dans le site[/quote]'),
(78, 'mais globalement je suis pa contre un reset'),
(79, 'G r&eacute;pondu &agrave; ce sujet.\r\nLes gens qui ont de bons portfeuilles seront capables de le reconstituer.\r\nEn effet en bourse tu n\'as pas le droit &agrave;  de la chance donc si tu as un bon portefeuille sans avoir tricher tu seras capable de te le reconstituer puisque tout le monde repart &agrave; 0 .\r\nCe qui ont un bon portefeuille avec bcp de chance il ne le conserveront pas longtemps car C prouv&eacute; statistiquement.\r\n\r\nA+\r\n\r\n\r\n\r\n[quote]et ceux ki n\'on pa trich&eacute; et ki on un bon portefeuil? ki te dit k\'il sont pour un reset?\r\n\r\n\r\n[quote]Bonjour,\r\n\r\nL\'administrateur ne voulant pas reseter le jeu, et les tricheurs ayant b&eacute;n&eacute;ficier depuis longue date du bug  o&ugrave; est l\'interet de son jeu ?\r\n\r\nC du n\'importe quoi :\r\nComment voulez vous faire de 80% voire du 200% en 1 ou 2 semaine.\r\nIl faut arretez les conneries meme avec un effet de levier 3.\r\n\r\n\r\nDe +, je ne vois pas en quoi le reset gene l\'administrateur pour les raisons suivantes :\r\n - les meilleurs resteront les meilleurs\r\n - les comptes des mauvais seront augment&eacute;s\r\n - et le nouveau trader comme moi (les v&eacute;ritable et non des escrot) seront interess&eacute; par son jeu.\r\n\r\nMerci de bien vouloir exprimer vos opinions.\r\n\r\nSi personne n\'est favorable, je  serais dans l\'obligation de quitter son jeu inutile a mon sens et promouvoir d\'autres similaires.\r\n\r\n\r\nAussi, si vous etes de veritables trader comme je le suis, echangeons nos experiences vous pouvez me contactez pas messagerie dans le site[/quote][/quote]'),
(80, 'STRO soit St&eacute;phane,\r\n\r\nJ\'ai euhhhh 2007-1973 = 34 ans, je suis passionn&eacute; de bourse.\r\n\r\nCela fait maintenant 1-1,5 ans que je me consacre essentiellement &agrave; la bourse.\r\nMon ambition est la qu&ecirc;te continuelle pour am&eacute;liorer ses performances pour pouvoir vivre de la bourse.\r\n\r\nJ\'arrive &agrave; faire chaque mois une tr&egrave;s belle paye.\r\n\r\n'),
(81, 'J\'ai toujours pas recu ton message.'),
(82, 'Salut\r\n\r\nJe suis int&eacute;ress&eacute; d\'entrer dans ton groupe de trader.\r\n\r\n'),
(83, '\r\n\r\nJe serais d\'accord qu\'on fasse un reset des portefeuilles.\r\n[quote]Bonjour,\r\n\r\nL\'administrateur ne voulant pas reseter le jeu, et les tricheurs ayant b&eacute;n&eacute;ficier depuis longue date du bug  o&ugrave; est l\'interet de son jeu ?\r\n\r\nC du n\'importe quoi :\r\nComment voulez vous faire de 80% voire du 200% en 1 ou 2 semaine.\r\nIl faut arretez les conneries meme avec un effet de levier 3.\r\n\r\n\r\nDe +, je ne vois pas en quoi le reset gene l\'administrateur pour les raisons suivantes :\r\n - les meilleurs resteront les meilleurs\r\n - les comptes des mauvais seront augment&eacute;s\r\n - et le nouveau trader comme moi (les v&eacute;ritable et non des escrot) seront interess&eacute; par son jeu.\r\n\r\nMerci de bien vouloir exprimer vos opinions.\r\n\r\nSi personne n\'est favorable, je  serais dans l\'obligation de quitter son jeu inutile a mon sens et promouvoir d\'autres similaires.\r\n\r\n\r\nAussi, si vous etes de veritables trader comme je le suis, echangeons nos experiences vous pouvez me contactez pas messagerie dans le site[/quote]'),
(84, 'Bonjours a tous je vien de m\'inscrire sur ce site dan sle but de m\'entrainner &agrave; placer mon argent mais avant de commencer j\'aimerais savoir ce que signifie le therme liquidit&eacute; merci'),
(85, 'voici un site qui reprend toutes les action et sur lesquelles on retrouves l\'avis de diverse source pour savoir s\'il faut achetter vendre ou gardez.\r\n[url=&quot;http://www.marketadvices.com&quot;]http://www.marketadvices.com[/url]'),
(86, '\r\n\r\n\r\n[quote]STRO soit St&eacute;phane,\r\n\r\nJ\'ai euhhhh 2007-1973 = 34 ans, je suis passionn&eacute; de bourse.\r\n\r\nCela fait maintenant 1-1,5 ans que je me consacre essentiellement &agrave; la bourse.\r\nMon ambition est la qu&ecirc;te continuelle pour am&eacute;liorer ses performances pour pouvoir vivre de la bourse.\r\n\r\nJ\'arrive &agrave; faire chaque mois une tr&egrave;s belle paye.\r\n\r\n[/quote]\r\nbonjour STRO,  Rolandk5 au clavier,\r\nJe suis retrait&eacute; michelin (j\'en possede quelques actions)et mon ambition est d\'appr&eacute;hender un petit peu le monde la bourse, avant de faire fructifier mon portefeuille, pour pouvoir &quot;commun&eacute;ment nomm&eacute;&quot; arrondir ma retraite.\r\nJe suis en &eacute;quipe avec les LBA.\r\nPour l\'instant le seul secret boursier que j\'ai pu percer, et j\'en suis convaicu &quot;est le suivi r&eacute;gulier, &agrave; l\'heure et parfois m&ecirc;me &agrave; la minute de la bourse tout &agrave; fait n&eacute;c&eacute;ssaire pour gagner de l\'argent.\r\ncordialement'),
(87, '\r\n\r\n\r\n[quote]merci\r\n\r\n[/quote]\r\nLa bosse du commerce est d\'acheter&quot; pas cher &quot; et de revendre &quot;cher&quot;. pour les actions c\'est la m&ecirc;me chose. '),
(88, 'STRO cobien t\'arive a te faire? \r\nmoi j\'aimerais bien essayer plus tard mais ya des risques aussi. quelles actions tu prend??\r\nmerci de me repondre \r\n\r\n\r\n[quote]\r\n\r\n[quote]STRO soit St&eacute;phane,\r\n\r\nJ\'ai euhhhh 2007-1973 = 34 ans, je suis passionn&eacute; de bourse.\r\n\r\nCela fait maintenant 1-1,5 ans que je me consacre essentiellement &agrave; la bourse.\r\nMon ambition est la qu&ecirc;te continuelle pour am&eacute;liorer ses performances pour pouvoir vivre de la bourse.\r\n\r\nJ\'arrive &agrave; faire chaque mois une tr&egrave;s belle paye.\r\n\r\n[/quote]\r\nbonjour STRO,  Rolandk5 au clavier,\r\nJe suis retrait&eacute; michelin (j\'en possede quelques actions)et mon ambition est d\'appr&eacute;hender un petit peu le monde la bourse, avant de faire fructifier mon portefeuille, pour pouvoir &quot;commun&eacute;ment nomm&eacute;&quot; arrondir ma retraite.\r\nJe suis en &eacute;quipe avec les LBA.\r\nPour l\'instant le seul secret boursier que j\'ai pu percer, et j\'en suis convaicu &quot;est le suivi r&eacute;gulier, &agrave; l\'heure et parfois m&ecirc;me &agrave; la minute de la bourse tout &agrave; fait n&eacute;c&eacute;ssaire pour gagner de l\'argent.\r\ncordialement[/quote]'),
(89, 'Jour noir aujourd\'hui : m&ecirc;me LVMH est pass&eacute; en n&eacute;gatif... tout comme mon compteur... c quandque &ccedil;a remonte? \r\n\r\n\r\nMoi qui pensais avoir fait de bons placements...Bah normalement d\'apr&egrave;s les analyste &ccedil;a devrait monter... \r\nSont cons aussi ces analystes on croirais des voyantes : parfois c juste parfois c faux; mais jamais ils le reconnaissent et te disent pourquoi ils se sont tromp&eacute;s.\r\n\r\nBon allez bonnne soir&eacute;e\r\n\r\nG. serial looser qui regarde vers le haut (parce que &ccedil;a peut pas baisser bcp plus bas)'),
(90, 'J\'avais pas vu je ne sais aps si c pariel pour vous : \r\n\r\nYavait boursorama (merci didier) et absbourse mais yahoo propose aussi de tracer des courbes diverses (et ya des liens partout avec ce site) \r\n\r\nA gauche ya une rubrique cours puis une rubrique graphique et l&agrave; &quot;simple&quot; est coch&eacute;e avec un clic sur indicateur technique ya moyen de tracer des courbes.\r\n\r\nAvantage par rapport aux autres : il y a moyen de cumuler plusieurs types de courbes et les couleurs ne laissent aps la confusion possible. De plus il y a la l&eacute;gende... c con &agrave; dire puisque quand j\'&eacute;tais jeune on me disait un graphique sans courbe ce n\'est que des coups de crayon sur une feuille mais bon certains sites...\r\n\r\n\r\nEnfin bon ... c &agrave; essayer mais perso j\'ai bien aim&eacute;. pour les consensus par contre faut rester sur les autres sites :s'),
(91, '\r\nNormal,\r\n\r\nG du mal a comprendre pkoi tu ne veux pas rester puisque  100% des personnes qui ont r&eacute;pondu sont d\'accord pour un reset.\r\n\r\nBien evidement, le reset sera fait ap&egrave;s correction des bugs.\r\n\r\n\r\n[quote]J\'ai toujours pas recu ton message.[/quote]'),
(92, 'Bonjour,\r\n\r\nEst-ce que par hasard, le d&eacute;calage de 15 minutes entre le d&eacute;lai de la bourse et celui du site ne permettrait pas de voir les actions qui grimpent ou qui s\'&eacute;croulent dans la r&eacute;alit&eacute; et d\'agir en cons&eacute;quence sur le jeu ?'),
(93, '\r\nOui avec les cours on direct on peut avoir le cours de l\'action 15 minutes avant le site de nettrader.'),
(94, 'Si je fait un reset je devrai &eacute;galement supprimer la page des scores du mois dernier.'),
(95, 'Pour ma part, cela ne me pose pas de probl&egrave;mes de r&eacute;aliser un reset!\r\n\r\n\r\n[quote]Si je fait un reset je devrai &eacute;galement supprimer la page des scores du mois dernier.[/quote]'),
(96, 'Sinon avant ca pour corriger le probleme de triche je pourrai mettre en place un systeme empechant d\'effectuer une transaction 30 minutes apr&eacute;s l\'achat...'),
(97, 'non je ne touve pas normal qu\'il y ait 30 mn de decalage c\'est trop long a atendre entre lachat d\'une action et la vente, je prefere qu\'on fasse reset\r\n'),
(98, 'c\'est pas une question de noms d\'actions !! il y a plusieurs sortes d\'actions,\r\ncelles qui te raportent a long terme : pas marrant ( je trouve ) mais un bon placement pour quelqun qui veut gagner sans se pr&eacute;occuper de son argnt\r\ncelles a moyen terme ( 1 2 mois ) pour suivre plus facilement\r\ncelles a court terme, le &quot;day trading&quot; tu achetes quand  &ccedil;a commence a monter, et tu revends quand tu penses que &ccedil;a va se mettre a descendre ( ou quand &ccedil;a commence a descendre, carr&eacute;ment ) \r\n\r\nC\'est pas une question de soci&eacute;t&eacute;, a moins que tu t\'y connaisses en g&eacute;opolitique et que tu suives tout ce qui se passe dans le monde des affaires.\r\n\r\nFit ( comment &ccedil;a s\'&eacute;crit &ccedil;a  ? ^^ ) toi a ton instinct, et si &ccedil;a marche pas, apprends a te servire des nombreuses techniques qui existent pour choisir, mais pour les connaitre :: Google t\'aidera'),
(99, 'l\'argent disponible.\r\nen petites coupures, si tu pr&eacute;feres, pas plac&eacute;.'),
(100, 'il y a aucun d&eacute;calage.\r\n\r\n\r\nJe suis CONTRE un reset.. ou est l\'interet ? je suis pas la pour plafonner en haut du classement, mais pour apprendre, et avoir de plus en plus d\'argent est tr&egrave;s motivant !!! qu\'ils aillent se faire f***, ceux qui trichent, perso &ccedil;a me passe au dessus de la t&ecirc;te a 100 km !!!!!\r\n\r\nPS : Si vraiment &ccedil;a g&egrave;ne: d&eacute;nonciation, et RAZ forc&eacute;e, non ???'),
(101, 'daccord avec toi'),
(102, 'Laissezzz moi creuser jjuuuuussssttt\'\'\' unnnneee nuiiiittttt\r\n\r\n\r\nOhhh laaaaiiiiisssseez moi creuser!!!!!\r\n\r\n'),
(103, ' :roll: est-il normal qu\'une action puisse s\'executer en p&eacute;riode de fermeture de la bourse ? (achat ou vente)\r\nCel&agrave; m\'est arriv&eacute;.'),
(104, 'La protection du d&eacute;calage boursier a &eacute;t&eacute; enlev&eacute; et il est donc maintenant possible d\'acheter et vendre les actions en dehors de l\'ouverture de la bourse.\r\n\r\nCela pose t\'il un probleme ?\r\n\r\n\r\n[quote] :roll: est-il normal qu\'une action puisse s\'executer en p&eacute;riode de fermeture de la bourse ? (achat ou vente)\r\nCel&agrave; m\'est arriv&eacute;.[/quote]'),
(105, '\r\nnon pas de probl&egrave;me c\'&eacute;tait pour comprendre \r\nmerci\r\n\r\n\r\n[quote]La protection du d&eacute;calage boursier a &eacute;t&eacute; enlev&eacute; et il est donc maintenant possible d\'acheter et vendre les actions en dehors de l\'ouverture de la bourse.\r\n\r\nCela pose t\'il un probleme ?\r\n\r\n\r\n[quote] :roll: est-il normal qu\'une action puisse s\'executer en p&eacute;riode de fermeture de la bourse ? (achat ou vente)\r\nCel&agrave; m\'est arriv&eacute;.[/quote][/quote]'),
(106, 'Administrateur es tu l&agrave; ?  :wink: \r\n\r\nSi oui, qu\'en penses tu, est ce faisable ?\r\n\r\n(en fait la question n\'est pas la bonne, je pense que c\'est faisable assez facilement avec &ccedil;a [url=http://www.artichow.org/]http://www.artichow.org[/url] notamment. La vraie question serait plutot : as tu le temps d\'envisager de metrre des graphiques &agrave; disponibilit&eacute; des joueurs ? )[/url]'),
(107, 'Tiens, d\'ailleurs (et &ccedil;a n\'a rien &agrave; voir ! :)  )\r\nc\'est moi ou les balises URL ne marchent pas sur le forum ?\r\n\r\n\r\n[quote]Administrateur es tu l&agrave; ?  :wink: \r\n\r\nSi oui, qu\'en penses tu, est ce faisable ?\r\n\r\n(en fait la question n\'est pas la bonne, je pense que c\'est faisable assez facilement avec &ccedil;a [url=http://www.artichow.org/]http://www.artichow.org[/url] notamment. La vraie question serait plutot : as tu le temps d\'envisager de metrre des graphiques &agrave; disponibilit&eacute; des joueurs ? )[/url][/quote]'),
(108, 'Salut\r\n\r\nmerci pour le lien je connaissais pas !\r\n\r\nSinon pour les balises ca marche pas en effet. Peut etre corriger ca ce week end.'),
(109, 'ou comment passer de 25000 euros a 10000 euros, les pennys, ce sont ces petites actions, entre 2 et 8 euros, peuvent faire gagner beaucoup d\'argent... mais aussi en perdre !!!! \r\n\r\n :mrgreen: \r\n\r\n\r\nQuelqun pourrait il m\'aider a mieux gerer ces petites actions qui peuvent rapporter gros ???'),
(110, 'ca y est ca commance a remonter ouf!!!!!!\r\n\r\n[quote]Laissezzz moi creuser jjuuuuussssttt\'\'\' unnnneee nuiiiittttt\r\n\r\n\r\nOhhh laaaaiiiiisssseez moi creuser!!!!!\r\n\r\n[/quote]'),
(111, 'Vi vi vi et paf les ordres de vente pour les actions dont je n\'ai jamais pu me d&eacute;barasser !!! \r\n\r\nReste BNP PARIBAS... m&ecirc;me avec une hausse d\'enfer j\'aurais tout le temps demain de passer l\'ordre :s\r\n\r\n\r\n'),
(112, 'Tu n\'as pas plac&eacute; de stop-loss ?\r\n\r\nQuand tu prend position sur une action tu dois imp&eacute;rativement placer au moins un ordre pour ne pas d&eacute;passer les 20-25 % de pertes par exemple.'),
(113, 'Ayant deja remporte 2medailles sur 2 possibles, notre equipe est une des meilleures equipes. :oops:\r\n \r\n :D  Notre objectif etait d\'obtenir une medaille d\'or pour ce mois, chose quasi faite.. Ce n\'est plus qu\'une question de temps  :lol:  \r\n\r\n       Ceci etait un bilan, mais la question est que doit faire l\'equipe pour garde son meilleure niveau le mois prochain, qu\'elles sont les nouveaux objectifs et qu\'elle est la strategie de la reussite..  :wink: \r\n\r\n\r\ncensure par le chef de la team  :evil:  marechalguy a encore frappe.. lol'),
(114, 'le stop loss est il accessible sur nettrader ???'),
(115, 'un stop-loss c\'est un ordre &agrave; plage(expert) de valeur.\r\n\r\nTu le place par ex &agrave; -20% de la valeur d\'achat ( vente de \r\n 0 &agrave; 80euros par ex)\r\n\r\nhttp://blog.nettrader.fr/post/2006/07/22/%5BDEBUTANT-INITIE%5D-Les-ordres-dachat-et-de-vente-a-seuil-evitez-les-surprises\r\n\r\n[quote]le stop loss est il accessible sur nettrader ???[/quote]'),
(116, 'j\'ai pas compris comment ca fonctionnais le stop-loss. Comment on r&eacute;alise l\'operation pour eviter la perte.\r\n a Chaque fois que je defini un seuil il vend monaction direct :roll: \r\n\r\n[quote]un stop-loss c\'est un ordre &agrave; plage(expert) de valeur.\r\n\r\nTu le place par ex &agrave; -20% de la valeur d\'achat ( vente de \r\n 0 &agrave; 80euros par ex)\r\n\r\nhttp://blog.nettrader.fr/post/2006/07/22/%5BDEBUTANT-INITIE%5D-Les-ordres-dachat-et-de-vente-a-seuil-evitez-les-surprises\r\n\r\n[quote]le stop loss est il accessible sur nettrader ???[/quote][/quote]'),
(117, 'En fait moi aussi je suis nouveau mais je viens de faire une plus value de 24% en deux jours sur casino :D ...avec une moins value de 19% sut total  :? \r\n[/img]'),
(118, 'Je ne vois pas trop le probl&egrave;me, le but n\'est pas de faire le meilleur score.\r\nJe ne triche pas (&ccedil;a se voit en ce moment^^) mais je m\'interesse plus &agrave; mes r&eacute;sultat personels qu\'a ceux des autres.'),
(119, 'Disons que le cours de l\'action est &agrave; 110€.\r\n\r\nTu va cr&eacute;er 3 ordres.\r\n\r\nLe premier, un ordre d\'achat entre 0 € et 100 €\r\n\r\nLe deuxi&egrave;me, un ordre de vente entre 110 et -1 (infini)\r\n\r\nLe troisi&egrave;me un ordre de vente entre 0 € et 85 € (le stop-loss)\r\n\r\nTu peut maintenant laisser reposer tranquillement ton portef car tu sais que tu n\'auras pas de tr&eacute;s mauvaises surprises.\r\n\r\n\r\n[quote]j\'ai pas compris comment ca fonctionnais le stop-loss. Comment on r&eacute;alise l\'operation pour eviter la perte.\r\n a Chaque fois que je defini un seuil il vend monaction direct :roll: \r\n\r\n[quote]un stop-loss c\'est un ordre &agrave; plage(expert) de valeur.\r\n\r\nTu le place par ex &agrave; -20% de la valeur d\'achat ( vente de \r\n 0 &agrave; 80euros par ex)\r\n\r\nhttp://blog.nettrader.fr/post/2006/07/22/%5BDEBUTANT-INITIE%5D-Les-ordres-dachat-et-de-vente-a-seuil-evitez-les-surprises\r\n\r\n[quote]le stop loss est il accessible sur nettrader ???[/quote][/quote][/quote]'),
(120, 'Merci, je crois avoir compris comment faire et mon erreur.\r\nJe fesais l\'erreur en cr&eacute;ant un seul ordre de vente si je suis ton exemple je fesais un ordre de vente 85€ et 110€ donc a chaque fois il etait direct vendu. Je vais essayer ta technique des que j\'aurai des action valable sur du cour therme. ;-)\r\n\r\n\r\n'),
(121, 'Didier is back...\r\nCa a bien merd&eacute; pendant mon absence... Mais bon, si ca remonte, tout va bien.\r\nContent de vous revoir ! :lol: '),
(122, '\r\nNon C pire !!!!!\r\nDe gros gains assurer et ce tres rapidement.\r\n\r\n[quote]\r\nOui avec les cours on direct on peut avoir le cours de l\'action 15 minutes avant le site de nettrader.[/quote]'),
(123, '\r\nAdministrateur est tu donc pret pour un reset apr&egrave;s avoir corriger le bug que je vais t\'annoncer ?\r\n'),
(124, 'non au reset, on s\'en tape des abrutis qui trichent. Le plus interessant est notre portefeuille personnel. '),
(125, 'C\'est fait; j\'ai bonne espoir car il est vrai que l\'action a parfoit des pointes, encore faut il etre la...\r\n\r\n\r\nj\'envoi un message plus tard pour vous dire ce que j\'ai r&eacute;ussit a reprendre sur mon pactol de d&eacute;part ;)'),
(126, '[quote]non au reset, on s\'en tape des abrutis qui trichent. Le plus interessant est notre portefeuille personnel. [/quote]  \r\n\r\n100% d\'accord ! :mrgreen: \r\n'),
(127, '\r\nCOntent de te revoir aussi\r\n\r\nmerde par contre rien ne va plus je remonte... petit &agrave; petit mais bon...\r\n\r\nJe dois pas avoir les m&ecirc;mes actions que JF qui viens de me mettre 100€ dans la vue...\r\n\r\nBah tant pis mon temps viendra et &ccedil;a fera mal au moral des autres!!! :)\r\n\r\nGnnniiiiaaaaarrrrrcccc\r\n\r\n\r\nSeeU\r\n\r\nZOu'),
(128, 'Moi aussi je serai interess&eacute; pour int&eacute;grer votre groupe'),
(129, 'NON au reset mais lol ceux qui trichent on un reset mais pas les autres sinon ou est la motivation...\r\nBon trade\r\n\r\n\r\n[quote][quote]non au reset, on s\'en tape des abrutis qui trichent. Le plus interessant est notre portefeuille personnel. [/quote]  \r\n\r\n100% d\'accord ! :mrgreen: \r\n[/quote]'),
(130, '\r\n(somme du capital en fin de mois - somme du capital en debut de mois ) / somme du capital en debut de mois\r\n\r\nAinsi un joueur qui a un capital plus &eacute;lev&eacute; que les autres aura plus d\'influance sur le groupe que les autres joueurs.'),
(131, 'slt a tous moi aussi je sr&eacute; int&eacute;r&eacute;ss&eacute; si vous recruter jve bien fire parti de votre groupe'),
(132, '\r\n\r\n\r\nMoi aussi.'),
(133, '\r\n\r\n  Nettrader est un jeu. Avoir la possibilit&eacute; de visualiser le portefeuille des autres joueurs pourraient permettre une progression non pas seulement pour les d&eacute;butants mais aussi pour les plus exp&eacute;riment&eacute;s en la mati&egrave;re en remarquant une erreur dans une technique ou en d&eacute;couvrir une autre.'),
(134, '\r\n\r\n\r\n J\'ai 14 ans.Je suis en 3&egrave;me. La bourse m\'int&eacute;resse vus les profits potentiels.'),
(135, '\r\npermettre de visualiser les portefeuil des autre joueur est la meilleur amelioration a faire je pence,\r\nde 1 sa ne nui pa a la performance des joueur, de 2 sa permet au debutan comme moi de voir kel titre possede les meilleur et faire des recherche pour savoir pourkoi il a pri ce tittre au lieu d\'un autre...\r\net comme l\'a dit sese, c\'est un jeu nettrader\r\n'),
(136, 'Salut je suis interesser fortement quelles sont les autres conditions ? \r\nclavier qwerty pas d\'accent dsl \r\nBon trade\r\n\r\n\r\n[quote]Bonjour a tous, tradeurs et tradeuses  :!: \r\n\r\nLe but de ce groupe est d\'augmenter dans l\'entraide; pour postuler, il faut connaitre les bases, ne pas &ecirc;tre trop en perte ( nous avons un but de victoire, car il ne faut pas oublier que la bourse reste un jeu.. dangereux, certes, mais un jeu malgr&eacute; tout, et NetTrader le rappel admirablement )\r\n\r\nUn forum personnel sera cr&eacute;er sous peu, a moins qu\'une partie de Nettrader ne soit allou&eacute; aux forums de groupe, d\'ici quelques temps.\r\n\r\nEn esperant avoir beaucoup de r&eacute;ponses.\r\n\r\n\r\nLeoden, allias Florent, Tradeur fictif depuis 3 mois, interress&eacute; a la bourse depuis 2 ans.[/quote]'),
(137, 'Compte tenu de mes performances, je serais tent&eacute; de vouloir voir et comprendre les portefeuilles des joueurs qui r&eacute;ussisent bien.\r\nNettrader est un jeu, tout le monde le dit, mais si c\'est seulement un jeu, alors il n\'y a aucune raison de pouvoir voir le portefeuille d\'action des autres joueurs.\r\n\r\nSi Nettrader est un jeu de simulation boursi&egrave;re p&eacute;dagogique, alors non seulement il faudrait pouvoir voir les actions retenus par les autres joueurs mais &eacute;galement expliquer pourquoi ils ont choisi telle ou telle action.\r\n\r\nPour moi, Nettrader est un jeu de simulation boursi&egrave;re sans p&eacute;dagogie. J\'ach&egrave;te quelques actions selon un sch&eacute;ma donn&eacute; et je constate les pertes ou profits &eacute;ventuels. Au fur et &agrave; mesure j\'essaie d\'affiner ma strat&eacute;gie pour am&eacute;liorer mon portefeuille d\'action. Pour le moment cela ne marche pas, mais j\'esp&egrave;re y arriver petit &agrave; petit. Si on me donne tout de suite une quelconque solution ou le moyen de tricher, je crois que je ne voudrais plus jouer.\r\n\r\n[quote]\r\net comme l\'a dit sese, c\'est un jeu nettrader\r\n[/quote]'),
(138, 'normalement un jeu sa a toujours un but pedagogique tu pence pa JUP?\r\nsi comme tu l\'a dit tu prefere pofin&eacute; ta strategie en solo je te comprend et je respecte ce choix, personne ne t\'oblige a regarder les portefeuil des autre joueur (si cette modif est realis&eacute;).\r\nmoi je suis a 100% pour cette modif.');
INSERT INTO `f_corps` (`idmessage`, `contenu`) VALUES
(139, 'Se serai bien de cr&eacute;er une banque ou nous pourion acheter de l\'argent  par sms ou ticket surf et autre truc du genre se serai vraiment passe que quand on ach&egrave;te plein d\'action dum&egrave;me groupe sans avoir envie de les vendre et que lon a plus d\'argent on ne peut plus rien faire.'),
(140, '&quot;Mon &eacute;quipe est en cours de validation par l\'adminisrateur&quot;\r\n\r\nSalut, \r\n\r\nVous &ecirc;tes passionn&eacute;s de trading, boursicotez dans la vraie vie et souhaitez rompre la solitude du trader exp&eacute;riment&eacute; alors rejoignez-moi dans mon &eacute;quipe ou [u]envoyez-moi vos mails.[/u]\r\n\r\nNous cr&eacute;erons ainsi une communaut&eacute; de trader &eacute;ventuellement via MSN pour discuter et partager nos exp&eacute;riences.\r\n\r\nDans le cas o&ugrave; vous faites d&eacute;j&agrave; parti d\'une &eacute;quipe, rien n\'emp&ecirc;che d\'entrer en contact avec moi par mail puis MSN.\r\n\r\nA tous les pationn&eacute;s, une invitation est lanc&eacute;e ! Rejoignez-moi sans tarder.\r\n'),
(141, 'les totales debutant sont accept&eacute;s? :roll: \r\n\r\n\r\n'),
(142, '\r\nBonne id&eacute;e je trouve que ca peut faire progresser. C\'est donn&eacute; une id&eacute;e comment est constitu&eacute; le portefeuille des bon ....que d\'action a court terme ou d\'actions long termes ou melange 75% 25%  :neutral: '),
(143, '\r\nApres oui, pour vous aider mais pas pour l\'instant.\r\n\r\n[quote]les totales debutant sont accept&eacute;s? :roll: \r\n\r\n\r\n[/quote]'),
(144, 'A mon humble avis, \r\nrien ne te sert de t\'eparpiller pour acheter plein d\'actions. \r\n\r\nLe conseil que je pourrais te donner c\'est plut&ocirc;t de te focaliser sur ta strat&eacute;gie d\'investissement par exemple :\r\n&quot;rien ne t\'empeche de sortir un titre sur lequel tu es en perte pour aller sur l\'action que tu d&eacute;sires&quot;\r\n\r\nAinsi tu minimises ta perte et tu fais aussit&ocirc;t du gain.\r\nSi ta strat&eacute;gie reste mauvaise alors tu engloutira encore ta fortune.\r\n\r\nCQFD.\r\n\r\n\r\n[quote]Se serai bien de cr&eacute;er une banque ou nous pourion acheter de l\'argent  par sms ou ticket surf et autre truc du genre se serai vraiment passe que quand on ach&egrave;te plein d\'action dum&egrave;me groupe sans avoir envie de les vendre et que lon a plus d\'argent on ne peut plus rien faire.[/quote]'),
(145, 'ca remonte grave c cool\r\ntu fais un retour fracassant \r\n'),
(146, 'je ve bien faire parti de ton groupe moi\r\nh&eacute;h&eacute; j\'arrive a me faire plein de sous ces temps ci :)'),
(147, 'lol spy : merci INGENICO\r\n\r\nmoi je suissur INGENICO pour le tres long terme mais en bourse r&eacute;el.\r\nje suis deja a bcp de sous ....\r\n\r\n\r\n\r\n[quote]je ve bien faire parti de ton groupe moi\r\nh&eacute;h&eacute; j\'arrive a me faire plein de sous ces temps ci :)[/quote]'),
(148, 'oui pour le reset .les premiers non pas de probleme  donc il doivent pas avoir de souci , pour etre toujour premier  ou est le chalange des joueurs qui sont nouveau .\r\n\r\n\r\n'),
(149, '&lt;Deleted by STRO&gt;'),
(438, 'Nicolas (si je me peux me permettre de t\'appeler ainsi).\r\n \r\nJe te remercie grandement d\'avoir consacrer ton temps &agrave; mon  probl&egrave;me ce qui a permis aussi de faie &eacute;voluer ton site.\r\n\r\nJe reviens parmis les coll&egrave;gues traders continuer notre aventure.\r\n\r\nCordialement.'),
(439, '\r\nEh bien moi je dis tout simplement un grand bravo &agrave; un grand administrateur b&eacute;n&eacute;vole pour ce travail &agrave; 0.31 € pr&egrave;s, m&ecirc;me l\'administration fiscale ne t\'en tiendra pas rigueur  :lol: \r\nMais le joujou est encore cass&eacute; ce matin ? Tu es encore en train de le perfectionner Nicolas ? :) \r\n\r\n[quote]C\'est bon c\'est corrig&eacute;, il y a une erreur de 31 centimes mais je n\'arrive pas &agrave; voir d\'ou ca viens. \r\n\r\n\r\n[quote]Cool, Hairyspider et merci pour tes encouragements.\r\n\r\nMais pour rester honn&ecirc;te et en respect avec mon travail, je demande humblement de me retablir aux centimes mon compte de trading.\r\n\r\nAllez un petit effort admin, fais ta boucle &quot;while&quot; ou &quot;for&quot; et le tour est jou&eacute; et moi je peux rejouer.\r\n[/quote][/quote]'),
(150, '\r\nje suis d\'acord que ses le bordel comment on peut triche sa que toi l administrateur tu puisse rien faire je comprend pas lintere.les tricheur tu les vire et tu repard ton beug ses mieux d\'avoir un site serieux.\r\n'),
(151, '900% de benef c pa normal, normalement ce site reflete la realit&eacute; nn?\r\nc pa serieux sa\r\nsi ya des bug fo les trouv&eacute; et les reparer.'),
(152, 'On se calme !  :roll: \r\nC\'est pas l\'apocalypse non plus... Vous pouvez parler poliment aussi.\r\nJe trouve &ccedil;a dingue d\'&ecirc;tre aussi exigeant et arrogant en face d\'un administrateur b&eacute;n&eacute;vole (y a pas de pub sur le site!) qui met &agrave; disposition ce jeu qui est quand m&ecirc;me tr&egrave;s sympa!\r\nVoil&agrave; pour le coup de gueule.\r\n\r\nSinon pour le probl&egrave;me en question, le reset a mon avis c\'est trop radical et &ccedil;a ne satisfera pas une bonne partie des gens qui ne s\'int&eacute;ressent qu\'a leur propre portefeuille.\r\nUne solution qui pourrait contenter tout le monde : mettre une mention &quot;tricheur soup&ccedil;onn&eacute;&quot; &agrave; c&ocirc;t&eacute; des gens douteux dans le classement.\r\nOu carr&eacute;ment les exclure du classement (sans forc&eacute;ment effacer leur portefeuille)\r\n\r\nBref y a plein d\'autres solutions que le RAZ g&eacute;n&eacute;ral.  :D \r\n\r\n\r\n\r\n[quote]\r\nje suis d\'acord que ses le bordel comment on peut triche sa que toi l administrateur tu puisse rien faire je comprend pas lintere.les tricheur tu les vire et tu repard ton beug ses mieux d\'avoir un site serieux.\r\n[/quote]'),
(153, '\r\n\r\n\r\n[Merci il s\'agit d\'un site tr&egrave;s int&eacute;ressant pour moi qui est d&eacute;butant. Le gratuit est si rare de nos jours. :D '),
(154, '\r\n\r\n\r\n53 ans d&eacute;j&agrave;, j\'y connais pas grand chose mais je m\'accroche. Comme je n\'ai pas de liquidit&eacute; &agrave; placer je m\'amuse.\r\nJe constate une chose on gagne un peu mais on peut perdre beaucoup, apr&egrave;s beaucoup d\'erreurs qui m\'ont cout&eacute; une bonne partie de mon capital de d&eacute;part, je remonte petit &agrave; petit.\r\nBonne chance &agrave; tous. :lol:  \r\n'),
(155, '\r\nlol je crois qu\'il n\'y a jamais eu autant de choses gratuites qu\'aujourd\'hui !\r\n :mrgreen: \r\n\r\n[quote]\r\n\r\n\r\n[Merci il s\'agit d\'un site tr&egrave;s int&eacute;ressant pour moi qui est d&eacute;butant. Le gratuit est si rare de nos jours. :D [/quote]'),
(156, 'Bonjour tous !\r\nComment arrivez vous &agrave; calculer le cout des ordres de vente/achat que vous effectuez ?\r\n\r\nMerci d\'avance de vos r&eacute;ponses :) '),
(157, 'Bon, au temps pour moi... j\'ai trouv&eacute; dans la FAQ !\r\nj\'aurais du regarder avant...\r\n\r\nBref je le mets quand meme ici, si y en a que &ccedil;a int&eacute;resse :\r\n\r\n[b]taxe = Valeur &eacute;chang&eacute;e * 0.3588%[/b]\r\n\r\n[i]sachant que valeur &eacute;chang&eacute;e = quantit&eacute; * valeur unitaire\r\net que  le pourcentage vient du calcul suivant :\r\nLa taxe du jeu est de 0.3% du montant &eacute;chang&eacute;, qu\'il faut augmenter des 19.6% de TVA, d\'o&ugrave; le pourcentage :\r\n0.3%*(1+19.6%) = 0.3588%[/i]'),
(158, 'Faire un reset sans corriger les bugs c\'est strictement inutile. Et me dire &quot;je dit c\'est quoi le probleme si tu promet de faire un reset&quot; je trouve ca tr&eacute;s pu&eacute;rile.\r\n\r\nDeusio je suis &eacute;tudiant et qui plus est j\'ai des difficult&eacute;s et donc pas l\'envie de sacrifier mon temps pour des tricheurs. C\'est leur problemes s\'il passent leurs journ&eacute;es &agrave; tricher sur le jeu juste pour p&ecirc;ter les scores je trouve juste ca path&eacute;tique..\r\n\r\nJ\'apprecie ta participation toutefois je t\'assure que ca ne me d&eacute;rangera pas si tu arretes de jouer.\r\n\r\nUn jour ou l\'autre la situation sera regl&eacute;. La seule chose que vous pouvez faire c\'est de me donner des solutions plutot que de remonter sans arret le probleme de triche.\r\n\r\n[quote]Bon, fo arreter les conneries :\r\nAdministrateur BOUGE TOI BON SANG !!!\r\nAs tu remarque que tu as des futurs Warrent BUFFET, ils ont 16 ans &agrave; tout casser et vont faire exploser WallStreet .\r\nCeux sont des g&eacute;nies, des dieux .... des ..... tricheurs ? en meme pas 2 mois d\'inscription.\r\n\r\nVoici les ferformance :\r\nPseudonyme	Date inscr.	Capital inscr.	Portefeuille	Plus value\r\nbigbenlb	27/02/2007	10363.61 €	107891.28 €	916.74 %\r\nmarechal_guy	15/01/2007	50465.78 €	313009.80 €	297.75 %\r\nmikyzell	15/01/2007	10000.00 €	31909.59 €	179.75 %\r\n\r\n\r\npenses tu ke * par 10 un capital en 1 mois C normal ?\r\nje les paies 100 000€ / mois pour me faire fructifier 1 000 000€/\r\n\r\nAlors BOUGES TOI ADMIN !!!!!\r\nF&eacute; ton reset bordel !!!\r\net corrige T bug !!!\r\n\r\nY \'a des traders serieux ICI !!!!\r\n\r\n\r\n[/quote]'),
(159, 'En faite tu demandes a l\'admin de faire un reset a tout ce qui sont devan toi.. Moi sa me derange pas, meme en repartan de zero j\'arrive a te battre. Ma technique est plutot bonne et je ne te permet pas de me traite de tricheur.Tu sais pa komen je fonctionne en bourse alors soit pa jaloux d\'etre battu. Si tu veu me confier 100 000€, je suis pret a te donner 500 000€ deux ou trois mois apres. Essaye de te renseigne sur les gens avant de les juge svp et au faite ca va faire depuis septembre que je suis inscrit meme si j\'ai du raz mon compte une fois, et oui la bourse est aleatoire et souvent capricieuse (on gagne pa tout le tps), je suis un habitue du site.. enfin vu ke tu es un genie toi, je ne vai rien t\'apprendre. J\'ai pa 16ans dsl.. enfin bonne chance pr le mois prochain, car chak mois ta plus value est de zero donc c un peu kom si tu reparte de zero. je compren pa ton raisonnemen.. et si il y a des gens qui trichent j aimerai bien savoir komen??\r\n\r\n\r\n\r\n[quote]Bon, fo arreter les conneries :\r\nAdministrateur BOUGE TOI BON SANG !!!\r\nAs tu remarque que tu as des futurs Warrent BUFFET, ils ont 16 ans &agrave; tout casser et vont faire exploser WallStreet .\r\nCeux sont des g&eacute;nies, des dieux .... des ..... tricheurs ? en meme pas 2 mois d\'inscription.\r\n\r\nVoici les ferformance :\r\nPseudonyme	Date inscr.	Capital inscr.	Portefeuille	Plus value\r\nbigbenlb	27/02/2007	10363.61 €	107891.28 €	916.74 %\r\nmarechal_guy	15/01/2007	50465.78 €	313009.80 €	297.75 %\r\nmikyzell	15/01/2007	10000.00 €	31909.59 €	179.75 %\r\n\r\n\r\npenses tu ke * par 10 un capital en 1 mois C normal ?\r\nje les paies 100 000€ / mois pour me faire fructifier 1 000 000€/\r\n\r\nAlors BOUGES TOI ADMIN !!!!!\r\nF&eacute; ton reset bordel !!!\r\net corrige T bug !!!\r\n\r\nY \'a des traders serieux ICI !!!!\r\n\r\n\r\n[/quote]'),
(160, 'C\'est une tres bonne idee ce forum.. :D  Ce qui serai parfait, c\'est que tout le monde s\'investi et discute sans que ce soit nawak pour l\'instant ca va mais faudra surveille  :evil: \r\n\r\n\r\n[quote]Alors que pensez-vous de ce forum ?\r\n\r\nQu\'aimerai vous voir modifi&eacute; ou ajout&eacute; dans ce forum ?[/quote] '),
(161, 'Bonjour &agrave; tous,\r\nLa qualit&eacute; d\'un Forum se reconnait, tout d\'abord par quelques formules de politesse, (tr&eacute;s simples, et connues de tous) comme &quot;Bonjour, bonsoir&quot;\r\n   Puis par la qualit&eacute; et le respect des id&eacute;es de tous,sans insolences\r\nEt enfin je pense par une orthographe ,sans &ecirc;tre plusque parfaite car ce n\'est pas l\'apanage de chacun, correcte et digne de nos &quot;certificats d\'&eacute;tudes&quot;.\r\nJe me pose la question de savoir pourquoi,vous vous impatientez de l\'voir notre administrateur bouger, alors qu\'il vous a immediatement propos&eacute; que vous lui &eacute;criviez.(pour lui expliquer quel &eacute;tait le bug).Nous ne voyons pas sur ce forum si cela a &eacute;t&eacute; r&eacute;alis&eacute;) et pourtant, vu la v&eacute;h&eacute;mence avec laquelle vous vilipendez ce dernier, j\'aimerai le connaitre..... Merci par avance de bien vouloir me l\'&eacute;xpliquer .\r\ncordialement              rolandk5\r\n\r\n[quote]Bon, fo arreter les conneries :\r\nAdministrateur BOUGE TOI BON SANG !!!\r\nAs tu remarque que tu as des futurs Warrent BUFFET, ils ont 16 ans &agrave; tout casser et vont faire exploser WallStreet .\r\nCeux sont des g&eacute;nies, des dieux .... des ..... tricheurs ? en meme pas 2 mois d\'inscription.\r\n\r\nVoici les ferformance :\r\nPseudonyme	Date inscr.	Capital inscr.	Portefeuille	Plus value\r\nbigbenlb	27/02/2007	10363.61 €	107891.28 €	916.74 %\r\nmarechal_guy	15/01/2007	50465.78 €	313009.80 €	297.75 %\r\nmikyzell	15/01/2007	10000.00 €	31909.59 €	179.75 %\r\n\r\n\r\npenses tu ke * par 10 un capital en 1 mois C normal ?\r\nje les paies 100 000€ / mois pour me faire fructifier 1 000 000€/\r\n\r\nAlors BOUGES TOI ADMIN !!!!!\r\nF&eacute; ton reset bordel !!!\r\net corrige T bug !!!\r\n\r\nY \'a des traders serieux ICI !!!!\r\n\r\n\r\n[/quote]'),
(162, 'Bonjour,\r\nNous attendons toujour l\'annonce???\r\na bient&ocirc;t        rolandk5\r\n\r\n[quote]non au reset, on s\'en tape des abrutis qui trichent. Le plus interessant est notre portefeuille personnel. [/quote]'),
(163, '         Bonjour spy, heureux de faire ta connaissance\r\n\r\n  C\'est vrai que je suis alle un peu fort sur le forum mais ce cher monsieur m\'avait agac&eacute; de persecuter l\'administrateur. Je suis pas sur a cent pour cent bien sur, mais ca fait un momen ke je suis la bourse et je connai donc un peu les valeurs moyennes ce qui me permet de savoir si l\'action est a vendre ou a acheter. Je ne peu pa trop te devoile mes techniques mais je te conseille de ne pas voir qu\'a court terme car c\'est assez difficile surtout si tu es pas tout le tps devant ton pc. Mon conseil principal est de ne pas tro eparpiller ton argent o debut car si tu veu faire bcp d\'argent, il faut miser gros.C\'est risque mais c\'est le seul moyen d\'avoir un portefeuille plus important, apres tu pourra elargir ton champs d\'action. Essaye de bien suivre une action pendant 2 ou 3 semaine et tu verra tout seul a kel moment, il vau mieux vendre ou acheter.Tu peux essaye aussi de suivre l\'actu des entreprise par exemple : probleme airbus 380 = chute de l\'action eads , plusieurs sucides dans l\'usine renault = chute de l\'action renault; enfin tu voi ce que je veu dire. Bien sur, ces informations sont pass&eacute;es. Moi j\'ai surveille l\'action BNP Paribas qui etait descendu tres bas vers les 78€ alors qu\'elle etait pa loin des 90€, une grosse entreprise ne peut pas s\'effondre comme ca et elle alle donc remonte peut etre sur le loin terme mais elle ne pouvai pa s\'ecroule alors j\'en est achete a 78€ et la elles sont a 80€. Ah oui, autre conseil ne t\'atten pas k\'une action prenne 10€, il fau savoir se debarrasse de l\'action. D\'ailleurs quand tu fai une mauvaise operation, chose qui arrive ne t\'entete pas dessus et debarrasse toi d\'elle. Il y a plein plein de petit detail que je ne peu pa te dire si il faudrai que j\'ecrive un bouquin, chose faite par d\'autre personne.Dernier conseil avant de partir, regarde boursorama ou ce genre de site car il influence les gens a petit portefeuille qui joue reel a la bourse par consequence il influence un peu la bourse ;-) O faite, pour commencer regarde les grosses entreprises c\'est plus facile : total, carrefour, etc.. Petit information que tu dois savoir surment, c\'est que tu peu achete des actions a la baisse autrement dit tu peu vendre des actions que tu n\'as pas encore ce qui te permet d\'avoir un plus grand portefeuille mais n\'oublie pa qu\'il faudra surmen les racheter plus tard. Une action qui risque de baisser, c\'est bien celle de OL groupe car aucun club de football n\'a reussi &agrave; la bourse meme pas les grands clubs tels que Manchester United. Voila, j\'espere que ca pourra te permette d\'avancer un peu. Au faite, il faut du feeling et beaucoup de chance aussi ;-) Bon courage et Bonne chance...'),
(164, 'Voila ce qu\'il m\'avait ecrit..\r\n\r\nj\'ai lu votre message sur le forum et j\'ai &eacute;t&eacute; fortement impressionn&eacute; par vos propos et l\'assurance dont vous avez fait par.\r\nau fait moi je suis un etudiant de 21ans et je commence a m\'interess&eacute; a la bourse et je voul&eacute; vous demander a vous qui &eacute;tes un initi&eacute; de bien vouloire me donn&eacute; quelques conseils pour bien debut&eacute;, j\'ai deja fait des recherche sur le web mais rien ne vaut les conseils d\'un expert comme on dit.\r\nje vous en serais tres reconn&eacute;ssant. '),
(165, 'Et toi mon tit marechal, tu en es ou avk l\'otre gars qui tavai demande des conseils?'),
(166, 'Alle voir sur le forum general, dans suggestion je croi puis dans REACTION DE L\'ADMINISTRATEUR BORDEL..'),
